create table if not exists public.single_use_access_offers (id uuid primary key default gen_random_uuid(), partner_program_id uuid not null references public.partner_programs(id) on delete cascade, business_id uuid not null references public.businesses(id) on delete cascade, name text not null, description text, price_cents integer not null default 0 check(price_cents>=0), quantity integer not null default 1 check(quantity>0), enabled boolean not null default true, expires_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.single_use_access_purchases (id uuid primary key default gen_random_uuid(), offer_id uuid not null references public.single_use_access_offers(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, status text not null default 'purchased' check(status in ('purchased','redeemed','expired','cancelled')), purchased_at timestamptz not null default now(), redeemed_at timestamptz, unique(offer_id,user_id,status));
create index if not exists single_use_access_offers_business_idx on public.single_use_access_offers(business_id,enabled);
create index if not exists single_use_access_purchases_user_idx on public.single_use_access_purchases(user_id,status);
alter table public.single_use_access_offers enable row level security;
alter table public.single_use_access_purchases enable row level security;
create or replace function public.get_single_use_access_offers() returns setof public.single_use_access_offers language sql security definer set search_path=public as $$ select o.* from public.single_use_access_offers o where o.enabled=true and (o.expires_at is null or o.expires_at>now()) order by o.created_at desc $$;
revoke all on function public.get_single_use_access_offers() from public, anon;
grant execute on function public.get_single_use_access_offers() to authenticated;
create or replace function public.purchase_single_use_access(p_offer_id uuid) returns public.single_use_access_purchases language plpgsql security definer set search_path=public as $$ declare o public.single_use_access_offers; p public.single_use_access_purchases; begin select * into o from public.single_use_access_offers where id=p_offer_id and enabled=true and (expires_at is null or expires_at>now()); if not found then raise exception 'offer unavailable'; end if; if exists(select 1 from public.single_use_access_purchases where offer_id=p_offer_id and user_id=auth.uid() and status='purchased') then raise exception 'already purchased'; end if; insert into public.single_use_access_purchases(offer_id,user_id) values(p_offer_id,auth.uid()) returning * into p; return p; end $$;
revoke all on function public.purchase_single_use_access(uuid) from public, anon;
grant execute on function public.purchase_single_use_access(uuid) to authenticated;
create or replace function public.redeem_single_use_access(p_purchase_id uuid) returns public.single_use_access_purchases language plpgsql security definer set search_path=public as $$ declare p public.single_use_access_purchases; begin update public.single_use_access_purchases set status='redeemed',redeemed_at=now() where id=p_purchase_id and user_id=auth.uid() and status='purchased' returning * into p; if not found then raise exception 'access unavailable'; end if; return p; end $$;
revoke all on function public.redeem_single_use_access(uuid) from public, anon;
grant execute on function public.redeem_single_use_access(uuid) to authenticated;
create or replace function public.business_create_single_use_access_offer(p_partner_program_id uuid,p_name text,p_description text,p_price_cents integer,p_quantity integer,p_expires_at timestamptz default null) returns public.single_use_access_offers language plpgsql security definer set search_path=public as $$ declare pr public.partner_programs; o public.single_use_access_offers; tier text; begin select * into pr from public.partner_programs where id=p_partner_program_id and business_id in(select business_id from public.business_members where user_id=auth.uid()); if not found then raise exception 'program unavailable'; end if; select lower(business_tier::text) into tier from public.businesses where id=pr.business_id; if tier not in ('growth','enterprise') then raise exception 'single-use access sales require Growth or Enterprise'; end if; insert into public.single_use_access_offers(partner_program_id,business_id,name,description,price_cents,quantity,expires_at) values(pr.id,pr.business_id,p_name,p_description,greatest(0,p_price_cents),greatest(1,p_quantity),p_expires_at) returning * into o; return o; end $$;
revoke all on function public.business_create_single_use_access_offer(uuid,text,text,integer,integer,timestamptz) from public, anon;
grant execute on function public.business_create_single_use_access_offer(uuid,text,text,integer,integer,timestamptz) to authenticated;
